SELECT s.name, c.id, 'kit', 'unit', 1, 'unit'
FROM src s
JOIN public.categories c ON c.kind = 'kit' AND c.name = s.cat_name
WHERE NOT EXISTS (
  SELECT 1 FROM public.products p
  WHERE p.product_kind = 'kit' AND lower(p.name) = lower(s.name)
);

SELECT kind, count(*) FROM categories WHERE kind='kit' GROUP BY kind;
SELECT count(*) AS kit_products FROM products WHERE product_kind='kit';
